const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"referrer\" content=\"no-referrer\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>NPT | Anatomy</title><meta name=\"theme-color\" content=\"#151a20\"><script>document.documentElement.dataset.theme=localStorage.getItem(\"npt-theme\")||\"dark\";</script><style>@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap');\n:root{color-scheme:dark;--bg:#151a20;--surface:#1d242c;--surface2:#252e38;--ink:#f3f0e8;--muted:#a8b2bf;--line:#384452;--green:#a7bdd8;--accentink:#172433;--wash:#293b50;--danger:#f0aaa7;--shadow:0 24px 80px #0009}\n:root[data-theme=light]{color-scheme:light;--bg:#f4f1e9;--surface:#fffdf8;--surface2:#eeede7;--ink:#252d37;--muted:#606d7c;--line:#d5d9dc;--green:#465f7d;--accentink:#ffffff;--wash:#e2e8ef;--danger:#a33e3b;--shadow:0 24px 80px #17243322}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px 'DM Sans',sans-serif;line-height:1.5}button,input,textarea{font:inherit}button{cursor:pointer;color:var(--ink);background:var(--surface2);border:1px solid var(--line);border-radius:6px;padding:10px 15px;font-weight:500;transition:background .15s,border-color .15s}button:hover{border-color:var(--muted);background:var(--line)}button:focus-visible,input:focus,textarea:focus{outline:2px solid var(--green);outline-offset:3px}button:disabled{opacity:.5;cursor:wait}.primary{background:var(--green);border-color:var(--green);color:var(--accentink);font-weight:700}.primary:hover{background:var(--green);filter:brightness(1.08);border-color:var(--green)}.shell{min-height:100vh;display:grid;grid-template-columns:208px minmax(0,1fr)}aside{display:flex;flex-direction:column;border-right:1px solid var(--line);padding:30px 18px;background:var(--bg);gap:50px}.brand{display:flex;align-items:center;gap:12px;font-size:23px;font-weight:700;letter-spacing:-.7px}.brand small{display:block;font:10px 'IBM Plex Mono',monospace;letter-spacing:2px;color:var(--muted);margin-top:3px}.mark{font:600 18px 'IBM Plex Mono',monospace;background:var(--green);color:var(--accentink);padding:8px;border-radius:4px}.brand .monogram{width:32px;height:32px;border:1px solid var(--line);display:grid;place-items:center;color:var(--green);font:16px 'IBM Plex Mono',monospace}nav{display:grid;gap:6px}nav button{text-align:left;border:0;background:transparent;color:var(--muted);padding:11px 13px}nav button[aria-current=page]{color:var(--ink);background:var(--surface2);box-shadow:inset 2px 0 var(--green)}.note{margin-top:auto;font:11px 'IBM Plex Mono',monospace;color:var(--muted);padding:14px 12px;border-top:1px solid var(--line)}main{padding:0 40px 30px;max-width:1480px;width:100%;margin:0 auto}header{height:80px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:12px}header>span{letter-spacing:1px;text-transform:uppercase}.avatar{font:11px 'IBM Plex Mono',monospace;background:var(--wash);padding:10px;color:var(--green);border:1px solid var(--line);border-radius:5px}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin:36px 0 30px}h1{margin:0;font-size:34px;line-height:1.25;letter-spacing:-1.1px;font-weight:600}h2{font-size:17px;font-weight:600;letter-spacing:-.2px;margin:0}.heading h2{font-weight:400;color:var(--green);margin-top:9px}.heading p{margin:9px 0 0}p{color:var(--muted);line-height:1.65}.eyebrow{font:10px 'IBM Plex Mono',monospace;letter-spacing:1.5px;color:var(--green)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-bottom:28px;border:1px solid var(--line);border-radius:8px;background:var(--surface);overflow:hidden}.stat{padding:21px 24px;color:var(--muted);font-size:12px;border-right:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:15px}.stat:last-child{border:0}.stat strong{font:400 32px 'IBM Plex Mono',monospace;color:var(--ink);letter-spacing:-1px}.stat small{color:var(--muted)}.panel{background:var(--surface);border:1px solid var(--line);border-radius:8px;overflow:hidden}.panelhead{padding:22px 24px;display:flex;align-items:center;justify-content:space-between;gap:15px}.panelhead .actions button{font-size:12px}.panelhead .actions button[id^=tab-]{border-color:transparent;background:transparent;color:var(--muted);padding:8px 11px}.panelhead .actions button[id^=tab-].primary{color:var(--green);background:var(--wash);border-color:var(--line)}.filters{padding:0 24px 22px;display:flex;gap:12px;align-items:center}.filters>input{max-width:340px}.inline{display:flex;gap:10px;align-items:center;margin:0;white-space:nowrap;font-weight:400;color:var(--muted);font-size:12px}.inline input{width:175px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left;white-space:nowrap}th{background:var(--surface2);color:var(--muted);font:10px 'IBM Plex Mono',monospace;text-transform:uppercase;letter-spacing:1px}th,td{padding:18px 24px;border-bottom:1px solid var(--line)}td{font-size:13px}tr:last-child td{border-bottom:0}tbody tr:hover{background:var(--surface2)}td strong{font-weight:500;display:block}td small{display:block;color:var(--muted);font-size:12px;margin-top:5px}td:first-child strong{font:12px 'IBM Plex Mono',monospace}td button{padding:7px 11px;font-size:12px;background:transparent}.badge{display:inline-flex;gap:7px;align-items:center;color:var(--green);background:var(--wash);font-size:11px;padding:5px 10px;border-radius:4px}.badge:before{content:'';width:5px;height:5px;border-radius:50%;background:currentColor}.badge.closed{color:var(--muted);background:var(--surface2)}.empty{padding:64px 24px;text-align:center;color:var(--muted)}.empty h2{color:var(--ink)}.empty p{font-size:13px}.empty button{margin:10px 4px}.foot{font:10px 'IBM Plex Mono',monospace;color:var(--muted);margin-top:24px;display:flex;justify-content:space-between;letter-spacing:.3px}.sessiontools{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:24px}.tool{padding:24px}.tool p{font-size:12px}.search{width:250px;padding:9px 12px}.back{color:var(--muted);background:transparent;border:0;padding:0;margin-bottom:22px;font-size:12px}.back:hover{background:transparent;color:var(--green)}label{display:block;font-size:12px;font-weight:500;margin:19px 0 8px;color:var(--ink)}input,textarea{width:100%;border:1px solid var(--line);border-radius:5px;padding:11px 12px;background:var(--bg);color:var(--ink)}input::placeholder,textarea::placeholder{color:var(--muted);opacity:.75}textarea{height:140px;resize:vertical}.split{display:grid;grid-template-columns:1fr 1fr;gap:16px}dialog{color:var(--ink);background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:30px;width:min(550px,94vw);max-height:90dvh;box-shadow:var(--shadow)}dialog::backdrop{background:#060b0bb3;backdrop-filter:blur(5px)}dialog h2{font-size:21px}dialog form>.actions{margin-top:24px;justify-content:flex-end}.error{color:var(--danger);white-space:pre-wrap}.qrbox{text-align:center}.qrbox h1{font-size:25px;margin-top:17px}.qrbox canvas{display:block;margin:24px auto;max-width:100%;background:#fff;border-radius:4px}.qrbox input{font:10px 'IBM Plex Mono',monospace}.checkin{max-width:450px;margin:9vh auto;padding:32px;background:var(--surface);border:1px solid var(--line);border-radius:10px}.checkin .brand{font-size:17px}.checkin h1{margin-top:30px}.checkin button{width:100%;margin-top:22px}.checkin h2{margin-top:16px}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:50;background:var(--green);color:var(--accentink);padding:12px 20px;border-radius:5px;font-size:13px;box-shadow:var(--shadow)}hr{border:0;border-top:1px solid var(--line)}.hint{border:1px solid var(--line);background:var(--surface2);padding:20px;border-radius:6px;margin-top:20px}.themeButton{min-width:75px}a{color:var(--green)}\n@media(min-width:1500px){main{padding:0 64px 36px}.heading{margin-top:45px}}@media(max-width:1000px){.shell{grid-template-columns:166px minmax(0,1fr)}main{padding:0 24px 24px}aside{padding:27px 12px}.filters{flex-wrap:wrap}.heading h1{font-size:30px}.stat{padding:18px}.stat strong{font-size:26px}}@media(max-width:760px){.shell{display:block}aside{display:none}main{padding:0 16px 24px}header{height:68px}.heading{margin:28px 0 22px;align-items:flex-start;flex-wrap:wrap;gap:18px}h1{font-size:28px}.heading p{font-size:12px}.stats{margin-bottom:20px}.stat{padding:15px 12px;display:block;font-size:10px}.stat strong{display:block;margin-top:9px;font-size:27px}.panelhead{padding:17px 16px;flex-wrap:wrap}.filters{padding:0 16px 18px;gap:10px}.filters>input{max-width:none}.inline{flex:1}.inline input{width:100%}th,td{padding:16px}.sessiontools{grid-template-columns:1fr;gap:12px}.tool{padding:20px}.split{grid-template-columns:1fr}.checkin{margin:30px 16px;padding:25px}.checkin h1{font-size:28px}.foot{font-size:9px}.qrbox canvas{width:260px;height:260px}.panelhead .actions{gap:4px}.panelhead .actions button{padding:8px 10px}dialog{padding:24px}}\r\n\nselect{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:5px;background:var(--bg);color:var(--ink);font:inherit}.danger{color:var(--danger)}.removed-row{display:flex;align-items:center;justify-content:space-between;padding:13px 0;border-bottom:1px solid var(--line)}\n.monogram svg{width:28px;height:28px}.brand .monogram{width:38px;height:38px;color:var(--green);border:0}</style><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2032%2032%22%20fill%3D%22%23e8b3a8%22%3E%3Cg%20transform%3D%22rotate(-38%2016%2016)%22%3E%3Cpath%20d%3D%22M9%2012h14c1-3%203-4%205-3s3%204%201%207c2%203%201%206-1%207s-4%200-5-3H9c-1%203-3%204-5%203s-3-4-1-7c-2-3-1-6%201-7s4%200%205%203Z%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E\"></head><body><div id=\"app\"></div><dialog id=\"modal\"></dialog><script src=\"https://cdnjs.cloudflare.com/ajax/libs/qrious/4.0.2/qrious.min.js\"></script><script>const boneIcon=\"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" viewBox=\\\"0 0 32 32\\\" fill=\\\"currentColor\\\"><g transform=\\\"rotate(-38 16 16)\\\"><path d=\\\"M9 12h14c1-3 3-4 5-3s3 4 1 7c2 3 1 6-1 7s-4 0-5-3H9c-1 3-3 4-5 3s-3-4-1-7c-2-3-1-6 1-7s4 0 5 3Z\\\"/></g></svg>\";\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet managerToken=sessionStorage.getItem(\"npt-manager-session\")||\"\";\nlet sessions=[],active=null,records=[],demo=false,filter='all',month='',query='';const app=$('#app');\nasync function api(path,method='GET',data){const base=window.NPT_API_BASE||'';if(window.NPT_STATIC&&!base)throw Error('Backend setup is in progress. You can view the demo below.');const r=await fetch(base+'/api/'+path,{method,headers:{'content-type':'application/json','authorization':managerToken?'Bearer '+managerToken:''},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok){const error=Error(d.error||'Request failed');error.status=r.status;throw error}return d}\nfunction toast(s){const t=document.createElement('div');t.className='toast';t.textContent=s;document.body.append(t);setTimeout(()=>t.remove(),3000)}\nconst today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'});\nconst dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'}):'No date';\nfunction frame(content,section=\"sessions\"){app.innerHTML='<div class=\"shell\"><aside><div class=\"brand\"><span class=\"monogram\" aria-hidden=\"true\">'+boneIcon+'</span><div>NPT<small>ANATOMY</small></div></div><nav><button data-nav=\"sessions\" onclick=\"dashboard()\">Sessions</button><button data-nav=\"roster\" onclick=\"roster()\">Roster</button><button data-nav=\"settings\" onclick=\"settings()\">Settings</button></nav></aside><main><header><span>Anatomy / Attendance</span><div class=\"actions\"><button class=\"themeButton\" onclick=\"toggleTheme()\" aria-label=\"Switch colour theme\">'+(document.documentElement.dataset.theme==='dark'?'☀ Light':'☾ Dark')+'</button><button onclick=\"settings()\">Settings</button><button onclick=\"logout()\">Sign out</button></div></header>'+content+'<div class=\"foot\"><span>NPT · Anatomy</span><span>'+(demo?'Demo data':'')+'</span></div></main></div>';document.querySelectorAll('nav [data-nav]').forEach(button=>button.setAttribute('aria-current',button.dataset.nav===section?'page':'false'))}\nasync function load(){try{sessions=await api('sessions');demo=false;dashboard()}catch(e){if(e.status===401){managerToken='';sessionStorage.removeItem('npt-manager-session');loginPage();return}frame('<div class=\"empty\"><h1>Unable to load sessions</h1><p>'+esc(e.message)+'</p><button onclick=\"load()\">Retry</button></div>')}}\nfunction dashboard(){active=null;const live=sessions.filter(s=>!s.archived);frame('<div class=\"heading\"><h1>Anatomy sessions</h1><button class=\"primary\" onclick=\"editSession()\">＋ New session</button></div><div class=\"stats\"><div class=\"stat\">Sessions<strong>'+live.length+'</strong></div><div class=\"stat\">Upcoming<strong>'+live.filter(s=>s.date>=today()).length+'</strong></div><div class=\"stat\">Places booked<strong>'+live.reduce((n,s)=>n+s.people.length,0)+'</strong></div></div><div class=\"panel\"><div class=\"panelhead\"><div class=\"actions\">'+['all','upcoming','past','deleted'].map(f=>'<button id=\"tab-'+f+'\" onclick=\"setFilter(\\''+f+'\\')\">'+({all:'All dates',upcoming:'Upcoming',past:'Past',deleted:'Deleted'}[f])+'</button>').join('')+'</div><button onclick=\"load()\">Refresh</button></div><div class=\"filters\"><input id=\"sessionSearch\" placeholder=\"Search sessions\" value=\"'+esc(query)+'\" oninput=\"query=this.value;sessionRows()\"><label class=\"inline\">Month <input type=\"month\" value=\"'+esc(month)+'\" onchange=\"month=this.value;sessionRows()\"></label><button onclick=\"query=\\'\\';month=\\'\\';filter=\\'all\\';dashboard()\">Clear</button></div><div class=\"tablewrap\" id=\"sessionRows\"></div></div>');sessionRows()}\nfunction setFilter(f){filter=f;sessionRows()}\nfunction sessionRows(){const list=sessions.filter(s=>(filter==='deleted'?s.archived:!s.archived)&&(filter==='all'||filter==='deleted'||(filter==='past'?s.date<today():s.date>=today()))&&(!month||s.date.startsWith(month))&&((s.title+' '+(s.label||'')+' '+s.date).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>(a.date+' '+(a.time||'')).localeCompare(b.date+' '+(b.time||'')));for(const f of ['all','upcoming','past','deleted'])$('#tab-'+f)?.classList.toggle('primary',filter===f);$('#sessionRows').innerHTML=list.length?'<table><thead><tr><th>Date</th><th>Session</th><th>Places</th><th>Registration</th><th></th></tr></thead><tbody>'+list.map(s=>'<tr><td>'+esc(dateLabel(s.date))+'<small>'+esc(s.time||'')+'</small></td><td><strong>'+esc(s.title)+'</strong><small>'+esc(s.label||'')+'</small></td><td>'+s.people.length+' of '+s.capacity+' filled</td><td><span class=\"badge '+(s.registrationOpen!==false&&s.date>=today()&&s.people.length<s.capacity?'':'closed')+'\">'+(s.archived?'Deleted':s.date<today()?'Ended':s.people.length>=s.capacity?'Full':s.registrationOpen===false?'Closed':'Open')+'</span></td><td>'+(s.archived?'<button onclick=\"restoreSession(\\''+s.id+'\\')\">Restore</button>':'<button onclick=\"view(\\''+s.id+'\\')\">Open register</button>')+'</td></tr>').join('')+'</tbody></table>':'<div class=\"empty\">No sessions to show.</div>'}\nfunction loadDemo(){demo=true;filter='all';const d=today();sessions=[{id:'demo',title:'Upper limb anatomy',label:'Shoulder & brachial plexus',date:d,time:'18:00',open:true,registrationOpen:true,people:[{name:'Aisha',id:'demo-aisha'},{name:'Daniel',id:'demo-daniel'},{name:'Sarah',id:'demo-sarah'}]},{id:'demo2',title:'Thorax anatomy',label:'Heart & mediastinum',date:'2026-12-09',time:'18:00',open:false,people:[],registrationOpen:true},{id:'demo3',title:'Lower limb anatomy',label:'Hip & femoral triangle',date:'2026-10-28',time:'17:00',open:false,registrationOpen:false,people:[]}];dashboard()}\nfunction editSession(edit=false){const s=edit?active:{title:'',label:'',date:today(),time:'',endTime:'',capacity:4,defaultHours:2};const m=$('#modal');m.innerHTML='<h2>'+(edit?'Edit session':'New session')+'</h2><form id=\"sessionForm\"><label>Session name</label><input name=\"title\" required maxlength=\"150\" value=\"'+esc(s.title)+'\"><label>Date name (optional)</label><input name=\"label\" maxlength=\"150\" value=\"'+esc(s.label||'')+'\"><label>Date</label><input name=\"date\" type=\"date\" required value=\"'+esc(s.date)+'\"><div class=\"split\"><div><label>Start time (optional)</label><input name=\"time\" type=\"time\" value=\"'+esc(s.time||'')+'\"></div><div><label>End time (optional)</label><input name=\"endTime\" type=\"time\" value=\"'+esc(s.endTime||'')+'\"></div></div><div class=\"split\"><div><label>Volunteer limit</label><input name=\"capacity\" type=\"number\" min=\"1\" max=\"2000\" step=\"1\" required value=\"'+(s.capacity??4)+'\"></div><div><label>Default hours</label><input name=\"defaultHours\" type=\"number\" min=\"0.01\" max=\"24\" step=\"any\" required value=\"'+(s.defaultHours??2)+'\"></div></div><p id=\"formError\" class=\"error\"></p><div class=\"actions\"><button type=\"button\" onclick=\"closeModal()\">Cancel</button><button class=\"primary\">'+(edit?'Save changes':'Create session')+'</button></div></form>';m.showModal();$('#sessionForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.capacity=Number(d.capacity);d.defaultHours=Number(d.defaultHours);const saved=await api(edit?'sessions/'+active.id:'sessions',edit?'PATCH':'POST',d);closeModal();sessions=await api('sessions');await view(saved.id)}catch(e){$('#formError').textContent=e.message;button.disabled=false}}}\nfunction closeModal(){$('#modal').close()}\nasync function view(id){try{if(demo){active=sessions.find(s=>s.id===id);records=id==='demo'?[{id:'demo-aisha',time:new Date().toISOString()}]:[]}else{active=await api('sessions/'+id);records=active.records;sessions=sessions.map(s=>s.id===id?active:s)}renderRegister()}catch(e){toast(e.message)}}\nfunction renderRegister(){const s=active;frame('<div class=\"heading\"><div><button class=\"back\" onclick=\"load()\">← Sessions</button><h1>'+esc(s.title)+'</h1><p>'+esc(dateLabel(s.date))+(s.time?' · '+esc(s.time):'')+' · '+s.people.length+' of '+s.capacity+' places filled</p></div><div class=\"actions\"><button onclick=\"editSession(true)\">Edit session</button><button onclick=\"duplicate()\">Add another date</button><button class=\"danger\" onclick=\"deleteSession(\\''+s.id+'\\')\">Delete session</button></div></div><div class=\"sessiontools\"><div class=\"panel tool\"><h2>Registration</h2><p>'+(s.people.length>=s.capacity?'Full':s.registrationOpen===false?'Closed':'Accepting registrations')+'</p><div class=\"actions\"><button class=\"primary\" onclick=\"showQR(\\'register\\')\">Registration QR / link</button><button onclick=\"toggle(\\'registrationOpen\\')\">'+(s.registrationOpen===false?'Open registration':'Close registration')+'</button></div></div><div class=\"panel tool\"><h2>Sign-out</h2><p>Volunteers sign out with their email, hours and optional notes.</p><div class=\"actions\"><button class=\"primary\" onclick=\"showQR(\\'signout\\')\">Sign-out QR / link</button><button onclick=\"toggle(\\'open\\')\">'+(s.open?'Close sign-out':'Open sign-out')+'</button></div></div></div><div class=\"panel\"><div class=\"panelhead\"><div><h2>Register</h2><p>'+s.people.filter(p=>p.attendance==='Yes').length+' attended · '+s.people.reduce((n,p)=>n+(p.attendance==='Yes'?p.hours:0),0)+' hours</p></div><div class=\"actions\"><button onclick=\"exportCSV()\">Export CSV</button><button onclick=\"removedEntries()\">Cancelled / deleted</button><button onclick=\"view(\\''+s.id+'\\')\">Refresh</button></div></div><div style=\"padding:0 24px 20px\"><input class=\"search\" placeholder=\"Search name or email\" oninput=\"filterStudents(this.value)\"></div><div class=\"tablewrap\"><table><thead><tr><th>Name / email</th><th>Registered</th><th>Attended</th><th>Hours</th><th>Notes</th><th>Signed out (UK)</th><th></th></tr></thead><tbody>'+s.people.map(p=>'<tr data-student=\"'+esc((p.name+' '+p.email).toLowerCase())+'\"><td><strong>'+esc(p.name)+'</strong><small>'+esc(p.email)+'</small></td><td>'+ukTime(p.registeredAt)+'</td><td><span class=\"badge '+(p.attendance==='Yes'?'':'closed')+'\">'+p.attendance+'</span></td><td>'+p.hours+(p.attendance==='Yes'?'':' <small>not credited</small>')+'</td><td style=\"white-space:pre-wrap;min-width:160px;max-width:300px\">'+esc(p.notes||'—')+'</td><td>'+ukTime(p.signedOutAt)+(p.source==='manager correction'?'<small>Manager corrected · '+ukTime(p.updatedAt)+'</small>':'')+'</td><td><div class=\"actions\"><button data-id=\"'+p.id+'\" onclick=\"editPerson(this.dataset.id)\">Edit</button><button data-id=\"'+p.id+'\" onclick=\"deletePerson(this.dataset.id)\">Delete</button></div></td></tr>').join('')+'</tbody></table>'+(s.people.length?'':'<div class=\"empty\">No registrations yet.</div>')+'</div></div>')}\nfunction filterStudents(q){document.querySelectorAll('[data-student]').forEach(r=>r.hidden=!r.dataset.student.includes(q.toLowerCase()))}\nasync function toggle(field){if(demo){active[field]=!active[field];renderRegister();return}try{active=await api('sessions/'+active.id,'PATCH',{[field]:!(field==='registrationOpen'?active[field]!==false:active[field])});records=active.records;renderRegister()}catch(e){toast(e.message)}}\nfunction duplicate(){if(demo)return toast('Select Refresh to leave the demo.');const s=active;editSession();$('#sessionForm [name=title]').value=s.title;$('#sessionForm [name=time]').value=s.time||'';toast('Choose the new date and date name.')}\nfunction parseCSV(text){let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='\"'){if(quote&&text[i+1]==='\"'){cell+='\"';i++}else quote=!quote}else if((c===','||c==='\\t')&&!quote){row.push(cell);cell=''}else if(c==='\\n'&&!quote){row.push(cell.trim());rows.push(row);row=[];cell=''}else cell+=c}row.push(cell.trim());rows.push(row);return rows.filter(r=>r.some(x=>x.trim()))}\nfunction importRegister(){if(demo)return toast('Import is available in the live register.');const m=$('#modal');m.innerHTML='<h2>Import first names</h2><p>Use one column headed First name. Existing entries are kept.</p><input id=\"csvFile\" type=\"file\" accept=\".csv\"><textarea id=\"csvText\" style=\"margin-top:16px\" placeholder=\"First name\\nAisha\\nDaniel\"></textarea><p id=\"importError\" class=\"error\"></p><div class=\"actions\"><button onclick=\"closeModal()\">Cancel</button><button class=\"primary\" id=\"doImport\">Import</button></div>';m.showModal();$('#csvFile').onchange=async e=>{if(e.target.files[0])$('#csvText').value=await e.target.files[0].text()};$('#doImport').onclick=async()=>{try{let rows=parseCSV($('#csvText').value);if(rows.length&&/^(name|first name|full name)$/i.test(rows[0][0]))rows.shift();const people=rows.map(r=>({firstName:(r[0]||'').trim()}));if(!people.length||people.some(p=>!p.firstName))throw Error('Every row needs a first name.');active=await api('sessions/'+active.id,'PATCH',{people});records=active.records;closeModal();renderRegister()}catch(e){$('#importError').textContent=e.message}}}\nfunction exportCSV(){const safe=value=>{let s=String(value??'');if(/^[=+@\\-\\t\\r]/.test(s))s=\"'\"+s;return '\"'+s.replace(/\"/g,'\"\"')+'\"'};const rows=[['Name','Email','Session','Date','Attended','Hours contributed','Notes','Registered at (UTC)','Signed out (UTC)'],...active.people.map(p=>[p.name,p.email,active.title,active.date,p.attendance,p.hours,p.notes,p.registeredAt,p.signedOutAt])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\\r\\n')],{type:'text/csv;charset=utf-8'}));a.download='Anatomy-'+active.date+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}\nfunction qrImage(type,url,session){const qr=document.createElement('canvas');new QRious({element:qr,value:url,size:600,padding:32,foreground:'#000000',background:'#ffffff',level:'M'});const image=document.createElement('canvas');image.width=720;const ctx=image.getContext('2d');ctx.font='600 32px Arial';const wrap=text=>{const words=String(text||'').split(/\\s+/),lines=[];let line='';for(const word of words){const next=line?line+' '+word:word;if(ctx.measureText(next).width>624&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);return lines};const lines=wrap(session.title);const qrTop=132+lines.length*42;image.height=qrTop+620;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,image.width,image.height);ctx.fillStyle='#000000';ctx.textAlign='center';ctx.font='700 52px Arial';ctx.fillText(type==='register'?'Registration':'Sign out',360,77);ctx.font='600 32px Arial';lines.forEach((line,i)=>ctx.fillText(line,360,132+i*42,624));ctx.drawImage(qr,60,qrTop);return image.toDataURL('image/png')}\nfunction showQR(type){const url=location.origin+location.pathname+'?'+type+'='+active.id+(demo?'&demo=1':'');const m=$('#modal');m.innerHTML='<div class=\"qrbox\"><h2>'+(type==='register'?'Registration QR':'Sign-out QR')+'</h2>'+((type==='signout'&&!active.open)?'<p class=\"error\">Sign-out is closed. Open it before volunteers scan.</p>':'')+'<img id=\"qr\" alt=\"'+(type==='register'?'Registration':'Sign out')+' QR code for '+esc(active.title)+'\" style=\"display:block;width:300px;max-width:100%;height:auto;margin:24px auto;background:white;border-radius:4px\"><p id=\"qrError\" class=\"error\"></p><input id=\"qrLink\" aria-label=\"QR link\" readonly value=\"'+esc(url)+'\"><div class=\"actions\" style=\"justify-content:center;margin-top:20px\"><button id=\"copyImageQR\">Copy image</button><button id=\"downloadQR\">Save image</button><button id=\"copyQR\">Copy link</button><button id=\"previewQR\">Preview</button><button onclick=\"closeModal()\">Done</button></div></div>';m.showModal();let png;try{png=qrImage(type,url,active);$('#qr').src=png}catch(e){$('#qrError').textContent='QR unavailable. Use the link below.';$('#downloadQR').disabled=true;$('#copyImageQR').disabled=true}$('#copyQR').onclick=()=>navigator.clipboard.writeText(url).then(()=>toast('Link copied')).catch(()=>toast('Copy the link from the field.'));$('#previewQR').onclick=()=>window.open(url,'_blank','noopener');$('#downloadQR').onclick=()=>{const a=document.createElement('a');a.href=png;a.download='Anatomy-'+(type==='register'?'registration':'signout')+'-'+active.date+'.png';a.click()};$('#copyImageQR').onclick=async()=>{try{if(!navigator.clipboard?.write||!window.ClipboardItem)throw Error();const bytes=Uint8Array.from(atob(png.split(',')[1]),c=>c.charCodeAt(0));const blob=new Blob([bytes],{type:'image/png'});await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);toast('Image copied')}catch(e){toast('Right-click the image and choose Copy image, or save it.')}}}\nasync function settings(){frame('<div class=\"heading\"><h1>Settings</h1><button onclick=\"dashboard()\">Back to sessions</button></div><div class=\"panel\" style=\"padding:28px;max-width:700px\"><h2>Master Excel workbook</h2><div id=\"excelConnection\"><p>Loading connection…</p></div><hr style=\"margin:30px 0\"><h2>Shared manager access</h2><p>Use the manager password on any device to view the same register.</p><button onclick=\"logout()\">Sign out</button></div>','settings');try{const d=await api('excel');const target=$('#excelConnection');if(!target)return;const url=d.workbookUrl;const safeUrl=typeof url==='string'&&url.startsWith('https://')&&new URL(url).hostname.endsWith('.sharepoint.com');target.innerHTML=d.connected&&safeUrl?'<p>Automatic updates every minute. Microsoft may take longer to display changes.</p><p>Includes the Master register and a tab for each session. Edit names, attendance and sessions on this website.</p><a class=\"primary\" style=\"display:inline-block;padding:10px 15px;border-radius:6px;text-decoration:none\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"'+esc(url)+'\">Open master workbook ↗</a>':'<p>Excel is not connected.</p>'}catch(e){const target=$('#excelConnection');if(target)target.innerHTML='<p>'+esc(e.message)+'</p>'}}\nasync function publicPage(){const params=new URLSearchParams(location.search);if(params.has('cancel')){app.innerHTML='<div class=\"checkin\"><h1>Cancel registration</h1><p>This will release your place for another volunteer.</p><button id=\"cancelBooking\">Cancel my place</button><p id=\"publicError\" class=\"error\"></p></div>';$('#cancelBooking').onclick=async()=>{try{await api('cancel','POST',{token:params.get('cancel')});$('.checkin').innerHTML='<h1>Registration cancelled</h1><p>Your place is available again.</p>'}catch(e){$('#publicError').textContent=e.message}};return}const type=params.has('register')?'register':'signout',id=params.get(type)||params.get('checkin');let s;try{s=await api('public/'+encodeURIComponent(id))}catch(e){app.innerHTML='<div class=\"checkin\"><h1>Session unavailable</h1><p>'+esc(e.message)+'</p></div>';return}const registration=type==='register',closed=registration?(s.registrationOpen===false||s.past||s.remaining===0):!s.signOutAvailable;app.innerHTML='<div class=\"checkin\"><div class=\"brand\"><span class=\"monogram\" aria-hidden=\"true\">'+boneIcon+'</span>NPT · Anatomy</div><h1>'+(registration?'Register':'Sign out')+'</h1><h2>'+esc(s.title)+'</h2><p>'+esc(dateLabel(s.date))+(s.time?' · '+esc(s.time):'')+'</p>'+(registration?'<p>'+s.registered+' of '+s.capacity+' places filled</p>':'')+(closed?'<p>'+(registration?(s.remaining===0?'This session is full.':'Registration is closed.'):(s.past?'This session has ended. Contact the organiser for a correction.':'Sign-out opens on the session date.'))+'</p>':'<form id=\"publicForm\">'+(registration?'<label for=\"volunteerName\">Name</label><input id=\"volunteerName\" name=\"name\" required maxlength=\"120\" autocomplete=\"name\">':'')+'<label for=\"volunteerEmail\">'+(registration?'Email':'Email used to register')+'</label><input id=\"volunteerEmail\" name=\"email\" type=\"email\" required maxlength=\"254\" autocomplete=\"email\">'+(registration?'':'<label for=\"contributedHours\">Hours contributed</label><input id=\"contributedHours\" name=\"hours\" type=\"number\" min=\"0.01\" max=\"24\" step=\"any\" required value=\"'+s.defaultHours+'\"><label for=\"signoutNotes\">Notes (optional)</label><textarea id=\"signoutNotes\" name=\"notes\" maxlength=\"2000\"></textarea>')+'<button class=\"primary\">'+(registration?'Register':'Submit sign-out')+'</button><p class=\"error\" id=\"publicError\"></p></form>')+'</div>';if(closed)return;$('#publicForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));if(!registration)d.hours=Number(d.hours);const result=await api(type,'POST',{...d,session:id});const cancelUrl=result.cancelToken?location.origin+location.pathname+'?cancel='+encodeURIComponent(result.cancelToken):'';$('.checkin').innerHTML='<h1>'+(registration?(result.duplicate?'Already registered':'Registered'):'Signed out')+'</h1><h2>'+esc(s.title)+'</h2><p>'+esc(dateLabel(s.date))+'</p><p>'+(registration?'Your place is booked.':esc(result.name)+' · '+result.hours+' hours recorded. Attendance: Yes.')+'</p>'+(cancelUrl?'<p>Keep this link if you need to cancel:</p><a href=\"'+esc(cancelUrl)+'\">Cancel my registration</a><input aria-label=\"Cancellation link\" readonly value=\"'+esc(cancelUrl)+'\" style=\"margin-top:15px\">':'')}catch(e){$('#publicError').textContent=e.message;btn.disabled=false}}}\nif(['checkin','signout','register','cancel'].some(key=>new URLSearchParams(location.search).has(key)))publicPage();else if(managerToken)load();else loginPage();\r\n\nfunction toggleTheme(){const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;localStorage.setItem('npt-theme',t);document.querySelectorAll('.themeButton').forEach(b=>b.textContent=t==='dark'?'☀ Light':'☾ Dark')}\n\nfunction displayName(p){return p.name||p.firstName||''}\nfunction editPerson(id){const p=active.people.find(p=>p.id===id);if(!p)return;const m=$('#modal');m.innerHTML='<h2>Edit entry</h2><form id=\"editEntry\"><label>Name</label><input name=\"name\" required maxlength=\"120\" value=\"'+esc(p.name)+'\"><label>Email</label><input name=\"email\" type=\"email\" required maxlength=\"254\" value=\"'+esc(p.email)+'\"><div class=\"split\"><div><label>Attended</label><select name=\"attendance\"><option>Pending</option><option>Yes</option><option>No</option></select></div><div><label>Hours contributed</label><input name=\"hours\" type=\"number\" min=\"0.01\" max=\"24\" step=\"any\" required value=\"'+p.hours+'\"></div></div><label>Notes</label><textarea name=\"notes\" maxlength=\"2000\">'+esc(p.notes)+'</textarea><p>Hours count toward the roster only when attendance is Yes.</p><p class=\"error\" id=\"entryError\"></p><div class=\"actions\"><button type=\"button\" onclick=\"closeModal()\">Cancel</button><button class=\"primary\">Save changes</button></div></form>';m.showModal();$('#editEntry [name=attendance]').value=p.attendance;$('#editEntry').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.hours=Number(d.hours);active=await api('sessions/'+active.id+'/person','PATCH',{id,...d});records=active.records;closeModal();renderRegister()}catch(e){$('#entryError').textContent=e.message;button.disabled=false}}}\nfunction deletePerson(id){const person=active.people.find(p=>p.id===id);if(!person)return;confirmAction('Delete entry?','Remove '+displayName(person)+' from this register? You can restore it from Deleted entries.','Delete entry',async()=>{if(demo){active.removedPeople=[...(active.removedPeople||[]),{...person,removed:true}];active.people=active.people.filter(p=>p.id!==id)}else{active=await api('sessions/'+active.id+'/person','PATCH',{id,removed:true});records=active.records}renderRegister()})}\nfunction confirmAction(title,message,label,action){const m=$('#modal');m.innerHTML='<h2>'+esc(title)+'</h2><p>'+esc(message)+'</p><p class=\"error\" id=\"actionError\"></p><div class=\"actions\"><button onclick=\"closeModal()\">Cancel</button><button class=\"danger\" id=\"confirmAction\">'+esc(label)+'</button></div>';m.showModal();$('#confirmAction').onclick=async()=>{const button=$('#confirmAction');button.disabled=true;try{await action();closeModal()}catch(e){$('#actionError').textContent=e.message;button.disabled=false}}}\nfunction deleteSession(id){const s=sessions.find(s=>s.id===id)||active;if(!s)return;confirmAction('Delete session?','Delete '+s.title+' ('+dateLabel(s.date)+')? Registration and sign-out links will close. You can restore it from Deleted.','Delete session',async()=>{if(demo){s.archived=true;s.open=false;s.registrationOpen=false}else{await api('sessions/'+id,'DELETE');sessions=await api('sessions')}dashboard()})}\nasync function restoreSession(id){try{if(demo){const s=sessions.find(s=>s.id===id);s.archived=false}else{await api('sessions/'+id,'PATCH',{archived:false});sessions=await api('sessions')}dashboard();toast('Session restored. Registration and sign-out remain closed.')}catch(e){toast(e.message)}}\nfunction removedEntries(){const m=$('#modal'),people=active.removedPeople||[];m.innerHTML='<h2>Deleted entries</h2><p>Restore an entry to return it to the register.</p>'+people.map(p=>'<div class=\"removed-row\"><span>'+esc(displayName(p))+'</span><button data-id=\"'+esc(p.id)+'\" onclick=\"restorePerson(this.dataset.id)\">Restore</button></div>').join('')+(people.length?'':'<p>No deleted entries.</p>')+'<button style=\"margin-top:20px\" onclick=\"closeModal()\">Done</button>';m.showModal()}\nasync function restorePerson(id){try{if(demo){const p=active.removedPeople.find(p=>p.id===id);p.removed=false;active.people.push(p);active.removedPeople=active.removedPeople.filter(p=>p.id!==id)}else{active=await api('sessions/'+active.id+'/person','PATCH',{id,removed:false});records=active.records}closeModal();renderRegister();toast('Entry restored.')}catch(e){toast(e.message)}}\nfunction loginPage(){app.innerHTML='<div class=\"checkin\"><div class=\"brand\"><span class=\"monogram\" aria-hidden=\"true\">'+boneIcon+'</span>NPT · Anatomy</div><h1>Manager sign-in</h1><form id=\"loginForm\"><label for=\"managerPassword\">Password</label><input id=\"managerPassword\" name=\"password\" type=\"password\" required autocomplete=\"current-password\"><button class=\"primary\">Sign in</button><p class=\"error\" id=\"loginError\"></p></form><button class=\"themeButton\" aria-label=\"Switch colour theme\" onclick=\"toggleTheme()\">'+(document.documentElement.dataset.theme==='dark'?'☀ Light':'☾ Dark')+'</button></div>';$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const password=$('#managerPassword').value,legacyKey=localStorage.getItem('npt-admin-key')||undefined;const result=await api('auth/login','POST',{password,legacyKey});managerToken=result.token;sessionStorage.setItem('npt-manager-session',managerToken);localStorage.removeItem('npt-admin-key');await load()}catch(e){$('#loginError').textContent=e.message;button.disabled=false}}}\nasync function logout(){try{await api('auth/logout','POST')}catch(e){}managerToken='';sessionStorage.removeItem('npt-manager-session');sessions=[];active=null;records=[];demo=false;loginPage()}\n\nasync function roster(){active=null;frame('<div class=\"heading\"><h1>Volunteer roster</h1></div><div id=\"rosterContent\" class=\"panel\"><p style=\"padding:24px\">Loading…</p></div>','roster');try{const rows=await api('roster');$('#rosterContent').innerHTML='<div class=\"tablewrap\"><table><thead><tr><th>Name</th><th>Email</th><th>Completed sessions</th><th>Total hours</th></tr></thead><tbody>'+rows.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.email)+'</td><td>'+p.sessions+'</td><td>'+p.hours+'</td></tr>').join('')+'</tbody></table></div>'+(rows.length?'':'<div class=\"empty\">No volunteers registered yet.</div>')}catch(e){toast(e.message)}}\n\nfunction ukTime(value){return value?esc(new Date(value).toLocaleString('en-GB',{timeZone:'Europe/London'})):'—'}\n</script></body></html>\n";
